def parse_version(s: str):
    parts = s.split('.')
    # Reject empty components or trailing/leading dots
    if not parts or any(p == '' for p in parts):
        return None
    result = []
    for p in parts:
        # Each component must be non-empty and consist solely of ASCII decimal digits
        if not p.isascii() or not p.isdigit():
            return None
        # int() preserves leading zeros as integer values
        result.append(int(p))
    return result

